export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Derives a project key that collides with nothing in `taken` (chosen or
 * derived from the name alike), by appending `2`, `3`, … and trimming so the
 * result never exceeds four characters.
 */
export function uniqueKey(input: string, taken: Iterable<string>): string {
  const base = input.toUpperCase().slice(0, PROJECT_KEY_MAX_LENGTH);
  const used = new Set(taken);
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const digits = String(suffix);
    const candidate = `${base.slice(0, PROJECT_KEY_MAX_LENGTH - digits.length)}${digits}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique suffixes");
}

