import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectService from "@/server/services/project-service";
import * as issueService from "@/server/services/issue-service";
import * as usageService from "@/server/services/usage-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import { subscribe } from "@/lib/event-bus";
import type { Actor } from "@/types/member";

async function main() {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-sanity-"));
  const path = join(dir, "taskflow.db");
  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  const off = usageService.registerUsageListeners();

  try {
    const owner = await userRepo.insertUser({
      email: "owner@sanity.test",
      name: "Owner",
      passwordHash: "x",
    });
    const org = await orgRepo.insertOrg(
      { name: "Sanity Co", slug: "sanity-co", plan: "free" },
      owner.id,
    );
    await subscriptionRepo.insertSubscription(org.id, "free", "monthly");
    await memberRepo.insertMember(org.id, owner.id, "owner", null);
    const actor: Actor = { userId: owner.id, orgId: org.id, role: "owner" };

    // --- Report 2: key collision on create (Web Visitors / Web Vendors) ---
    const vendors = await projectService.createProject(actor, {
      orgId: org.id,
      name: "Web Vendors",
      slug: "web-vendors",
      key: "WV",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    console.log("vendors key:", vendors.key, "slug:", vendors.slug);

    // Archive it to make room (free plan = 2 projects; org has 1 so far).
    await projectService.archiveProject(actor, {
      orgId: org.id,
      projectId: vendors.id,
      archiveIssues: true,
    });

    // Report 1: after archiving the only project, creating a new one should work.
    const visitors = await projectService.createProject(actor, {
      orgId: org.id,
      name: "Web Visitors",
      slug: "web-visitors",
      key: "WV",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    console.log("visitors key (should differ from WV):", visitors.key, "slug:", visitors.slug);
    if (visitors.key === "WV") throw new Error("FAIL: key collision not resolved");

    // Report 3 analogue: new project takes the archived project's address.
    const visitors2 = await projectService.createProject(actor, {
      orgId: org.id,
      name: "Web Vendors",
      slug: "web-vendors",
      key: "WEND",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    console.log("second web-vendors slug (should differ from web-vendors):", visitors2.slug);
    if (visitors2.slug === "web-vendors") throw new Error("FAIL: archived slug not reserved");

    // Now restoring the originally archived "Web Vendors" should work, under its own slug.
    // First free a slot: free plan = 2 projects; currently live: visitors, visitors2 = 2. Need to archive one.
    await projectService.archiveProject(actor, {
      orgId: org.id,
      projectId: visitors2.id,
      archiveIssues: true,
    });

    const restoredVendors = await projectService.restoreProject(actor, org.id, vendors.id);
    console.log("restored vendors slug (should be original web-vendors):", restoredVendors.slug);
    if (restoredVendors.slug !== "web-vendors") throw new Error("FAIL: restore did not keep original slug");

    // Report 4: restoring should respect the quota. live count now: visitors(active), restoredVendors = 2 (free limit).
    let refused = false;
    try {
      await projectService.restoreProject(actor, org.id, visitors2.id);
    } catch (e) {
      refused = true;
      console.log("restore refused as expected:", (e as Error).message);
    }
    if (!refused) throw new Error("FAIL: restore should have been refused at quota");

    const usageAfterRefusal = await usageRepo.getUsage(org.id);
    console.log("projectsUsed after refused restore (should be 2):", usageAfterRefusal.projectsUsed);

    // Archive one again to make room, then restore and check usage increments immediately.
    await projectService.archiveProject(actor, {
      orgId: org.id,
      projectId: restoredVendors.id,
      archiveIssues: true,
    });
    const usageAfterArchive = await usageRepo.getUsage(org.id);
    console.log("projectsUsed after archive (should be 1):", usageAfterArchive.projectsUsed);

    await projectService.restoreProject(actor, org.id, restoredVendors.id);
    const usageAfterRestore = await usageRepo.getUsage(org.id);
    console.log("projectsUsed after restore (should be 2):", usageAfterRestore.projectsUsed);

    const recount = await usageService.recomputeUsage(org.id);
    console.log("recount agrees:", recount.projectsUsed === usageAfterRestore.projectsUsed);

    // Report 5: restoring a project that is not archived should be refused, no event.
    let events = 0;
    const offRestored = subscribe("project.restored", () => {
      events += 1;
    });
    let refusedLive = false;
    try {
      await projectService.restoreProject(actor, org.id, visitors.id); // visitors is live
    } catch (e) {
      refusedLive = true;
      console.log("restore-of-live refused as expected:", (e as Error).message);
    }
    offRestored();
    if (!refusedLive) throw new Error("FAIL: restoring a live project should be refused");
    if (events !== 0) throw new Error("FAIL: restoring a live project announced an event");

    // Report 6: status transitions.
    // Pause is always fine.
    const paused = await projectService.updateProject(actor, {
      orgId: org.id,
      projectId: visitors.id,
      status: "paused",
    });
    console.log("paused status:", paused.status);
    if (paused.status !== "paused") throw new Error("FAIL: status not persisted");

    // Paused project should refuse new issues.
    let issueRefused = false;
    try {
      await issueService.createIssue(actor, {
        orgId: org.id,
        projectId: visitors.id,
        title: "Should fail",
        description: null,
        status: "backlog",
        priority: "none",
        assigneeId: null,
        parentId: null,
        estimate: null,
        dueAt: null,
        labelIds: [],
      });
    } catch (e) {
      issueRefused = true;
      console.log("issue creation on paused project refused:", (e as Error).message);
    }
    if (!issueRefused) throw new Error("FAIL: paused project accepted a new issue");

    // Reactivate, then create an issue, then try to complete with open issue (should refuse).
    await projectService.updateProject(actor, {
      orgId: org.id,
      projectId: visitors.id,
      status: "active",
    });
    const issue = await issueService.createIssue(actor, {
      orgId: org.id,
      projectId: visitors.id,
      title: "Open issue",
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
    console.log("created issue:", issue.id);

    let completeRefused = false;
    try {
      await projectService.updateProject(actor, {
        orgId: org.id,
        projectId: visitors.id,
        status: "completed",
      });
    } catch (e) {
      completeRefused = true;
      console.log("complete refused with open issue:", (e as Error).message);
    }
    if (!completeRefused) throw new Error("FAIL: completed with an open issue");

    // Close the issue, then complete should succeed; completing again is a no-op.
    await issueService.changeIssueStatus(actor, {
      orgId: org.id,
      issueId: issue.id,
      status: "done",
    });
    const completed = await projectService.updateProject(actor, {
      orgId: org.id,
      projectId: visitors.id,
      status: "completed",
    });
    console.log("completed status:", completed.status);
    if (completed.status !== "completed") throw new Error("FAIL: completion did not persist");

    const completedAgain = await projectService.updateProject(actor, {
      orgId: org.id,
      projectId: visitors.id,
      status: "completed",
    });
    console.log("completed again status:", completedAgain.status);

    console.log("\nALL SANITY CHECKS PASSED");
  } finally {
    off();
    rmSync(dir, { recursive: true, force: true });
  }
}

main().catch((error) => {
  console.error("SANITY CHECK FAILED:", error);
  process.exitCode = 1;
});

